/** The initial shell covers a fractional top-edge prefix rounded beneath a sticky bar. */
export function viewportCapturePlan(
  top: number,
  height: number,
  viewportHeight: number,
  inset: number,
): {
  shellPrefix: { top: number; height: number } | null;
  tiles: { top: number; height: number }[];
} {
  if (!Number.isSafeInteger(inset) || inset < 0 || inset >= viewportHeight)
    throw new Error('A readiness overlay must leave a visible capture region.');
  const start = Math.max(top, inset);
  const prefixHeight = start - top;
  if (prefixHeight >= height)
    throw new Error('The initial overlay covers the entire readiness region.');
  return {
    shellPrefix: prefixHeight === 0 ? null : { top, height: prefixHeight },
    tiles: viewportTiles(start, height - prefixHeight, viewportHeight - inset),
  };

import {
  assertViewportRaster,
  viewportCapturePlan,
  viewportTiles,
} from '../Support/viewportRaster.ts';

test('rounded initial edges remain covered by the shell and all later pixels by clear viewport tiles', () => {
  const plan = viewportCapturePlan(103, 28587, 844, 104);
  assert.deepEqual(plan.shellPrefix, { top: 103, height: 1 });
  let next = 104;
  for (const tile of plan.tiles) {
    assert.equal(tile.top, next);
    assert.ok(tile.height <= 740);
    next += tile.height;
  }
  assert.equal(next, 103 + 28587);
  assert.equal(viewportCapturePlan(87, 17989, 1000, 87).shellPrefix, null);
  assert.equal(viewportCapturePlan(87, 17989, 1000, 87).tiles[0].height, 913);
  assert.throws(() => viewportCapturePlan(0, 10, 844, 844), /overlay/);
  assert.throws(() => viewportCapturePlan(0, 10, 844, 20), /overlay/);
});
